//! K6b's adapter: a K6 kernel model as K4's `SourceParts` (T3 K6b plan §3.2).
//!
//! - Nodes in the model's order (R1's order for RF-LARGE); node k is node k.
//! - Member k (0-based, in the model's order) has id k + 1, R1's 1-based member
//!   number, with the model's section and `y_reference` (P1's rule for
//!   RF-LARGE, ROOT's K6 ruling N4).
//! - Every restrained DOF is a constraint at 0.0.
//! - One nodal load per nonzero (DOF, value), with source id `k6:<global DOF>`.
//! - One station per member at fraction 0.5 (id = the member id), as K4's own
//!   adapter has, for R1's mid-span bending rows.
//! - No springs, directional springs or support groups: RF-LARGE and the
//!   DEC-053 nine have none.
//!
//! `K6Model` holds exact binary64 values already, so nothing is rounded here.

use super::super::models::K6Model;
use open_pipe_stress_frame_kernel::structural::retained_api::{
    Constraint, Dof, NodalLoad, PrimitiveSource, SourceError, SourceParts, Station, StraightMember,
};

/// The fraction of every member's station.
pub const STATION_FRACTION: f64 = 0.5;

/// The ledger source id of the load at a global DOF.
pub fn load_source_id(global_dof: usize) -> String {
    format!("k6:{global_dof}")
}

/// A member's K4 id: its 1-based position in the model's member order.
pub fn member_id(index: usize) -> u32 {
    u32::try_from(index + 1).expect("fewer than 2^32 members")
}

fn dof(global: usize) -> Dof {
    Dof::from_global(global)
}

/// The model's source parts (module documentation).
pub fn source_parts(model: &K6Model) -> SourceParts {
    let s = &model.section;
    let node = |i: usize| u32::try_from(i).expect("fewer than 2^32 nodes");
    SourceParts {
        nodes: model.nodes.iter().map(|(_, p)| *p).collect(),
        members: model
            .members
            .iter()
            .enumerate()
            .map(|(k, (_, i, j, y))| StraightMember {
                id: member_id(k),
                node_i: node(*i),
                node_j: node(*j),
                elastic_modulus: s.elastic_modulus,
                shear_modulus: s.shear_modulus,
                area: s.area,
                second_moment_y: s.second_moment_y,
                second_moment_z: s.second_moment_z,
                torsion_constant: s.torsion_constant,
                y_reference: *y,
            })
            .collect(),
        constraints: model
            .restrained_dofs()
            .into_iter()
            .map(|g| Constraint {
                dof: dof(g),
                value: 0.0,
            })
            .collect(),
        loads: model
            .loads
            .iter()
            .map(|&(g, value)| NodalLoad {
                dof: dof(g),
                value,
                source_id: load_source_id(g),
            })
            .collect(),
        stations: (0..model.member_count())
            .map(|k| Station {
                id: member_id(k),
                member: member_id(k),
                fraction: STATION_FRACTION,
            })
            .collect(),
        ..SourceParts::default()
    }
}

/// The model's `PrimitiveSource`, or K4's validation refusal.
pub fn source(model: &K6Model) -> Result<PrimitiveSource, SourceError> {
    PrimitiveSource::new(source_parts(model))
}

fn finish_selected(
    prep: Arc<CasePrep>,
    group: Arc<GroupPrep>,
    cache: GroupCache,
    states: Vec<PrecisionState>,
    selected: &PrecisionState,
    verification_precision: u32,
    mut attempts: Vec<AttemptRecord>,
    decision: &StopDecision,
    report: &VerificationState,
    certified: CertifiedPublication,
    geometry: Vec<BodyGeometry>,
) -> CaseOutcome {
    if !Arc::ptr_eq(&prep, &certified.prep) || selected.precision() != certified.precision {
        let stop = certificate_error(None, CertificateIssue::PairIdentity);
        if let Some(record) = attempts
            .iter_mut()
            .find(|a| a.precision == selected.precision() && a.outcome == AttemptOutcome::Accepted)
        {
            record.outcome = AttemptOutcome::Failed(AttemptReason::Stop(stop.clone()));
        }
        return finish_terminal(&stop, attempts, geometry);
    }
    // The certified bytes are moved, never re-rounded/reclassified here.
    let publication = certified.publication;
    let publication_radius_bits = certified.radii;
    let verification = match report.summary() {
        Ok(v) => v,
        Err(stop) => return finish_terminal(&stop, attempts, geometry),
    };
    for (body, bound) in verification.bound.iter().enumerate() {
        if bound.is_some_and(|b| !b.is_finite()) {
            return CaseOutcome::Unresolved {
                reason: UnresolvedReason::CertifiedBoundUnencodable { body: body as u32 },
                attempts,
                geometry,
            };
        }
    }
    let selected_record = attempts
        .iter()
        .find(|a| a.precision == selected.precision() && a.outcome == AttemptOutcome::Accepted)
        .cloned();
    let evidence = RetainedEvidence {
        method: METHOD_TOKEN,
        policy: POLICY,
        selected_precision: selected.precision(),
        verification_precision,
        stop_rule: decision.summary.clone(),
        floor_ratio_bits: FLOOR_RATIO_BITS,
        body_scales: publication.body_scales.clone(),
        input_derived_dofs: prep.source.constraints().iter().map(|c| c.dof).collect(),
        absolute_verified: publication
            .rows
            .iter()
            .filter_map(|r| match r.class {
                RowClass::AbsoluteVerified { bound_bits } => Some((r.id, bound_bits)),
                _ => None,
            })
            .collect(),
        not_covered: Vec::new(),
        unpublishable: publication
            .rows
            .iter()
            .filter(|r| r.class == RowClass::Unpublishable)
            .map(|r| (r.id, r.value))
            .collect(),
        pivot_margin_min: selected_record
            .as_ref()
            .and_then(|r| r.pivot_margin_min)
            .unwrap_or(0.0),
        rcond: selected_record
            .as_ref()
            .and_then(|r| r.rcond)
            .unwrap_or(0.0),
        rcond_label: RCOND_LABEL,
        residual_worst: selected_record
            .as_ref()
            .and_then(|r| r.residual_worst)
            .unwrap_or(0.0),
        corrections: selected.corrections(),
        geometry,
        source_encoding: prep.identity.clone(),
        ledger_encoding: prep.ledger.encoding(),
        retained_state_encoding: selected.encoding(),
        attempts,
        resolution_scale: verification
            .resolution
            .iter()
            .enumerate()
            .map(|(b, e)| (b as u32, e[0].to_bits(), e[1].to_bits()))
            .collect(),
        verification_estimate: decision.estimate_summary.clone(),
        verification_charge: decision.charge_summary.clone(),
        theta: verification
            .theta
            .iter()
            .enumerate()
            .map(|(b, t)| (b as u32, *t))
            .collect(),
        certified_bound: verification
            .bound
            .iter()
            .enumerate()
            .filter_map(|(b, v)| v.map(|v| (b as u32, v.to_bits())))
            .collect(),
        floor: decision.floor.as_ref().map(|f| {
            f.iter()
                .enumerate()
                .map(|(b, x)| (b as u32, x[0].to_bits(), x[1].to_bits()))
                .collect()
        }),
    };
    CaseOutcome::Selected(Box::new(RetainedSolve {
        prep,
        group,
        cache,
        states,
        selected: selected.precision(),
        evidence,
        publication,
        publication_radius_bits,
    }))
}

/// Geometry first, then the group's structure and ordering.
fn prepare_group(source: &PrimitiveSource) -> Result<GroupPrep, (Refusal, Vec<BodyGeometry>)> {
    let geometry = match geometry_first(source) {
        Ok(g) => g,
        Err(GeometryRefusal::MechanismWitnessed {
            body,
            rigid_parameters,
        }) => {
            return Err((
                Refusal::MechanismWitnessed {
                    body,
                    rigid_parameters,
                },
                Vec::new(),
            ))
        }
        Err(GeometryRefusal::Unavailable { body, error }) => {
            return Err((Refusal::GeometryUnavailable { body, error }, Vec::new()))
        }
    };
    let structure = Structure::new(source).map_err(|_| (Refusal::Structure, geometry.clone()))?;
    let ordering = order_free(source, &structure);
    let blocks = free_blocks(source, &structure, &ordering);
    Ok(GroupPrep {
        structure,
        ordering,
        geometry,
        blocks,
    })
}
pub(crate) fn resolution_scale<const L: usize>(
    layout: &[QuantityMeta],
    e_rows: &[Option<Wide<L>>],
    bodies: usize,
) -> Result<Vec<[f64; 2]>, AttemptStop>
where
    Wide<L>: SupportedWidth,
{
    let mut top = vec![[Wide::<L>::ZERO; 2]; bodies];
    for (meta, e) in layout.iter().zip(e_rows) {
        let (Some(e), Some(slot)) = (
            e,
            match meta.kind {
                Kind::Force => Some(0usize),
                Kind::Moment => Some(1),
                _ => None,
            },
        ) else {
            continue;
        };
        let current = &mut top[meta.body as usize][slot];
        if e.cmp_value(current) == CmpOrdering::Greater {
            *current = *e;
        }
    }
    top.iter()
        .map(|[fo, mo]| Ok([binary64_up(fo)?, binary64_up(mo)?]))
        .collect()
}

/// Item 6a's coupling in binary64: ê_fo = max(E_fo, fl(E_mo/L_b)),
/// ê_mo = max(E_mo, fl(L_b·E_fo)); a single-node body (L_b = 0) keeps E.
pub fn e_hat(e: [f64; 2], extent: f64) -> [f64; 2] {
    // V-K seeded fault VK-R02 (R7-M2): ê uncoupled.
    #[cfg(any(test, feature = "mutation-controls"))]
    if super::seeded::active(super::seeded::Fault::R02) {
        return e;
    }
    if extent == 0.0 {
        return e;
    }
    let [fo, mo] = e;
    [fo.max(mo / extent), mo.max(extent * fo)]
}

/// ê per body from finite E (item 6a). An ê that overflows binary64 while E
/// encodes (fl(L_b·E_fo) or fl(E_mo/L_b) beyond the range) is the same
/// terminal case as E's own overflow (ROOT's A3b ruling): V, the estimate's
/// threshold and the charge's allowance would be infinite, and no precision
/// can pass, so the verification stops with `ResolutionScale` (F2a:
/// `receipt_encoding`).
pub fn resolution_hats(
    resolution: &[[f64; 2]],
    extents: &[f64],
) -> Result<Vec<[f64; 2]>, AttemptStop> {
    resolution
        .iter()
        .zip(extents)
        .enumerate()
        .map(|(b, (e, &extent))| {
            let hat = e_hat(*e, extent);
            for (kind, v) in [(Kind::Force, hat[0]), (Kind::Moment, hat[1])] {
                if !v.is_finite() {
                    return Err(AttemptStop::ResolutionScale {
                        body: b as u32,
                        kind,
                    });
                }
            }
            Ok(hat)
        })
        .collect()
}

