/// A segment of the call in time order, with the case work charged through
/// its end.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Segment {
    pub label: String,
    pub end: u64,
}

/// The call's segments in the schedule's time order (module documentation).
pub fn segments(attempts: &[AttemptRecord]) -> Vec<Segment> {
    let mut out = Vec::new();
    let mut total = 0u64;
    for (i, a) in attempts.iter().enumerate() {
        let own_solve = own_total(a)
            .saturating_sub(a.verification_work)
            .saturating_sub(a.stop_rule_work);
        total = total
            .saturating_add(a.shared_work)
            .saturating_add(own_solve);
        out.push(Segment {
            label: format!("solve_{}", a.precision),
            end: total,
        });
        let verified =
            a.verification.is_some() || a.verification_work > 0 || a.verification_shared_work > 0;
        if verified {
            total = total
                .saturating_add(a.verification_shared_work)
                .saturating_add(a.verification_work);
            out.push(Segment {
                label: format!("verify_{}", a.precision),
                end: total,
            });
            if i > 0 && attempts[i - 1].stop_rule_work > 0 {
                total = total.saturating_add(attempts[i - 1].stop_rule_work);
                out.push(Segment {
                    label: format!("decide_{}", attempts[i - 1].precision),
                    end: total,
                });
            }
        }
    }
    out
}

/// Parity `w1_prefix_segments` for prefix j (1-based): the prefix call ended on
/// the case budget, and its first j segments equal the full call's (RV22-N3:
/// the binary's predicate, here so that it is tested).
pub fn prefix_matches(j: usize, full: &[AttemptRecord], prefix: &CaseOutcome) -> bool {
    let full_segments = segments(full);
    let own = segments(attempts_of(prefix));
    let budget_stop = matches!(
        prefix,
        CaseOutcome::Unresolved {
            reason: UnresolvedReason::Budget(_),
            ..
        }
    );
    budget_stop && own.len() >= j && full_segments.len() > j && own[..j] == full_segments[..j]
}

/// The prefix limits: every segment's end but the last (the last is the full
/// call).
pub fn prefix_limits(attempts: &[AttemptRecord]) -> Vec<(String, u64)> {
    let segs = segments(attempts);
    segs.iter()
        .take(segs.len().saturating_sub(1))
        .map(|s| (s.label.clone(), s.end))
        .collect()
}
}

/// Accumulates an integer model and converts it once.
struct Builder {
    points: Vec<(String, [i64; 3])>,
    members: Vec<(String, usize, usize)>,
    restraints: Vec<(usize, [bool; 6])>,
    loads: Vec<(usize, f64)>,
}

impl Builder {
    fn new() -> Self {
        Self {
            points: Vec::new(),
            members: Vec::new(),
            restraints: Vec::new(),
            loads: Vec::new(),
        }
    }
    fn node(&mut self, label: String, p: [i64; 3]) -> usize {
        self.points.push((label, p));
        self.points.len() - 1
    }
    /// A force (or, with `offset` 3, a moment) at `node`: each nonzero
    /// component `c * 2^exponent`, exact.
    fn load(&mut self, node: usize, offset: usize, v: [i64; 3], exponent: i32) {
        for (axis, &c) in v.iter().enumerate() {
            if c != 0 {
                assert!(c.unsigned_abs() < (1_u64 << 53));
                self.loads.push((
                    node * DOF_PER_NODE + offset + axis,
                    c as f64 * pow2(exponent),
                ));
            }
        }
    }
    fn finish(mut self, id: &str, source: &str, family: Family) -> K6Model {
        self.loads.sort_by_key(|&(dof, _)| dof);
        self.restraints.sort_by_key(|&(node, _)| node);
        let members = self
            .members
            .iter()
            .map(|(label, i, j)| {
                (
                    label.clone(),
                    *i,
                    *j,
                    p1_y_reference(self.points[*i].1, self.points[*j].1),
                )
            })
            .collect();
        K6Model {
            id: id.to_string(),
            source: source.to_string(),
            family,
            section: rf_large_section(),
            nodes: self
                .points
                .into_iter()
                .map(|(label, p)| (label, coordinates(p)))
                .collect(),
            members,
            restraints: self.restraints,
            loads: self.loads,
        }

pub(crate) fn order_free(source: &PrimitiveSource, structure: &Structure) -> Ordering {
    let free = source.free_dofs();
    let mut position = vec![usize::MAX; source.dof_count()];
    for (a, &g) in free.iter().enumerate() {
        position[g] = a;
    }
    let adjacency: Vec<Vec<usize>> = free
        .iter()
        .map(|&g| {
            structure
                .pattern
                .row(g)
                .iter()
                .filter_map(|&c| (position[c] != usize::MAX && c != g).then_some(position[c]))
                .collect()
        })
        .collect();
    let order = reverse_cuthill_mckee(&adjacency);
    let mut rank = vec![0usize; free.len()];
    for (k, &a) in order.iter().enumerate() {
        rank[a] = k;
    }
    let first: Vec<usize> = order
        .iter()
        .enumerate()
        .map(|(i, &a)| {
            adjacency[a]
                .iter()
                .map(|&b| rank[b])
                .chain(std::iter::once(i))
                .min()
                .unwrap_or(i)
        })
        .collect();
    let profile_entries = first.iter().enumerate().map(|(i, &f)| i - f + 1).sum();
    Ordering {
        free,
        position,
        order,
        rank,
        first,
        profile_entries,
    }
}

