pub(crate) fn certified<const L: usize>(
    uc: &Option<Wide<L>>,
    s: &Option<Wide<L>>,
) -> Option<Wide<L>>
where
    Wide<L>: SupportedWidth,
{
    match (uc, s) {
        (Some(a), Some(b)) => Some(if b.cmp_value(a) == CmpOrdering::Less {
            *b
        } else {
            *a
        }),
        (Some(a), None) => Some(*a),
        (None, Some(b)) => Some(*b),
        (None, None) => None,
    }
}

